"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[9984],{3331:(e,n,i)=>{i.d(n,{R:()=>o,x:()=>s});var t=i(36672);const r={},a=t.createContext(r);function o(e){const n=t.useContext(a);return t.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:o(e.components),t.createElement(a.Provider,{value:n},e.children)}},38187:(e,n,i)=>{i.r(n),i.d(n,{assets:()=>d,contentTitle:()=>s,default:()=>c,frontMatter:()=>o,metadata:()=>t,toc:()=>l});const t=JSON.parse('{"id":"2023/04/10","title":"2023-04-10","description":"Het LLama-effect: Het lek bracht een reeks open source alternatieven voor ChatGPT op gang.","source":"@site/i18n/nl/docusaurus-plugin-content-docs/current/2023/04/10.md","sourceDirName":"2023/04","slug":"/2023/04/10","permalink":"/nl/2023/04/10","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/nl/docusaurus-plugin-content-docs//current/2023/04/10.md","tags":[],"version":"current","frontMatter":{"localized_date":"10 april 2023","top_news":"Het LLama-effect: Het lek bracht een reeks open source alternatieven voor ChatGPT op gang."},"sidebar":"defaultSidebar","previous":{"title":"2023-04-11","permalink":"/nl/2023/04/11"},"next":{"title":"2023-04-09","permalink":"/nl/2023/04/09"}}');var r=i(23420),a=i(3331);const o={localized_date:"10 april 2023",top_news:"Het LLama-effect: Het lek bracht een reeks open source alternatieven voor ChatGPT op gang."},s="2023-04-10",d={},l=[{value:"Het LLama-effect: Het lek bracht een reeks open source alternatieven voor ChatGPT op gang.",id:"het-llama-effect-het-lek-bracht-een-reeks-open-source-alternatieven-voor-chatgpt-op-gang",level:2},{value:"Van diep naar lang leren?",id:"van-diep-naar-lang-leren",level:2},{value:"EY krijgt verbod op nieuwe controleopdrachten in Duitsland.",id:"ey-krijgt-verbod-op-nieuwe-controleopdrachten-in-duitsland",level:2},{value:"Zonsondergang op de Zuidpool",id:"zonsondergang-op-de-zuidpool",level:2},{value:"Nederlandse journalist die kritisch schrijft over China doelwit in intimidatieschema",id:"nederlandse-journalist-die-kritisch-schrijft-over-china-doelwit-in-intimidatieschema",level:2},{value:"USPS faciliteit in Utah doet niets anders dan handschrift ontcijferen",id:"usps-faciliteit-in-utah-doet-niets-anders-dan-handschrift-ontcijferen",level:2},{value:"Apple blijft zich inspannen om te voorkomen dat winkels zich verenigen",id:"apple-blijft-zich-inspannen-om-te-voorkomen-dat-winkels-zich-verenigen",level:2},{value:"PL/Rust 1.0: nu een vertrouwde taal voor Postgres",id:"plrust-10-nu-een-vertrouwde-taal-voor-postgres",level:2},{value:"Twitter blokkeert Likes en Retweets die Substack vermelden",id:"twitter-blokkeert-likes-en-retweets-die-substack-vermelden",level:2},{value:"Z-bibliotheek laat gebruikers fysieke boeken delen.",id:"z-bibliotheek-laat-gebruikers-fysieke-boeken-delen",level:2},{value:"Perseus - NextJS alternatief in Rust",id:"perseus---nextjs-alternatief-in-rust",level:2},{value:"Een Baby GPT",id:"een-baby-gpt",level:2},{value:"Twee soorten software ingenieurs",id:"twee-soorten-software-ingenieurs",level:2},{value:"Advanced Linux Programming (2001)",id:"advanced-linux-programming-2001",level:2},{value:"Een CERN voor Open Source Grootschalige AI",id:"een-cern-voor-open-source-grootschalige-ai",level:2},{value:"Permafrost engine - Een OpenGL RTS game engine geschreven in C.",id:"permafrost-engine---een-opengl-rts-game-engine-geschreven-in-c",level:2},{value:"Het sluiten van een oude SSH verbinding",id:"het-sluiten-van-een-oude-ssh-verbinding",level:2},{value:"Flatcar Container Linux",id:"flatcar-container-linux",level:2},{value:"Microsoft / JARVIS: een systeem om LLM&#39;s te verbinden met de ML-gemeenschap",id:"microsoft--jarvis-een-systeem-om-llms-te-verbinden-met-de-ml-gemeenschap",level:2},{value:"Bolvormige tokamak bereikt cruciale plasmatemperaturen",id:"bolvormige-tokamak-bereikt-cruciale-plasmatemperaturen",level:2},{value:"De eerste &#39;paaseieren&#39; van het spel waren een daad van bedrijfsrebellie...",id:"de-eerste-paaseieren-van-het-spel-waren-een-daad-van-bedrijfsrebellie",level:2},{value:"Modulaire fouten in Rust",id:"modulaire-fouten-in-rust",level:2},{value:"68-95-99.7 Regel",id:"68-95-997-regel",level:2},{value:"UnicodePlots",id:"unicodeplots",level:2},{value:"Digitale verzamelobjecten op Instagram loopt af",id:"digitale-verzamelobjecten-op-instagram-loopt-af",level:2},{value:"De uitspraak die de toekomst van bibliotheken bedreigt",id:"de-uitspraak-die-de-toekomst-van-bibliotheken-bedreigt",level:2},{value:"Do Kwon zette illegaal geld van LUNA om in Bitcoin.",id:"do-kwon-zette-illegaal-geld-van-luna-om-in-bitcoin",level:2},{value:"Interview met Andrew Kelley (Zig Creator) (2021)",id:"interview-met-andrew-kelley-zig-creator-2021",level:2},{value:"Supavisor - een Postgres connection pooler geschreven in Elixir",id:"supavisor---een-postgres-connection-pooler-geschreven-in-elixir",level:2},{value:"Nieuwe beschuldigingen van plagiaat tegen Roy Lichtenstein",id:"nieuwe-beschuldigingen-van-plagiaat-tegen-roy-lichtenstein",level:2}];function g(e){const n={a:"a",del:"del",h1:"h1",h2:"h2",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.header,{children:(0,r.jsx)(n.h1,{id:"2023-04-10",children:"2023-04-10"})}),"\n",(0,r.jsx)(n.h2,{id:"het-llama-effect-het-lek-bracht-een-reeks-open-source-alternatieven-voor-chatgpt-op-gang",children:"Het LLama-effect: Het lek bracht een reeks open source alternatieven voor ChatGPT op gang."}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://thesequence.substack.com/p/the-llama-effect-how-an-accidental",children:"Origineel"}),'.\nHet toevallige lek van "Llama", een LLM model, heeft een open-source alternatieve beweging op gang gebracht voor modellen als GPT-4 en Cohere die alleen via API\'s beschikbaar zijn. Sinds het lek zijn onder meer Alpaca, Vicuna, Koala, ColossalChat en ChatLLama uitgebracht, allemaal gebouwd op Llama. De open-source alternatieven voor deze modellen hebben niet hetzelfde prestatieniveau getoond tot de Llama release. Het uitlekken van Llama is een van de grootste vonken van innovatie gebleken in de open-source LLM ruimte, waar een oorlog tussen open-source en API-gebaseerde distributie dreigt. Het LLama-effect heeft bewezen dat open source een levensvatbaar distributiemechanisme is voor basismodellen, en er zijn enkele interessante bronnen van innovatie in de LLM-ruimte.']}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35504428",children:"Discussion Service"}),".\nHet 'LLama Effect' lek heeft open-source alternatieven voor ChatGPT aangewakkerd, en heeft de aandacht getrokken van techneuten. GPT-4 geeft blijk van meer significante intelligentie en biedt redeneer- en generalisatiemogelijkheden dan zijn voorganger GPT-3. AI-tekstmodellen begrijpen ruimtelijk redeneren en kunnen puzzels begrijpen, maar handmatige fijnafstemming is noodzakelijk. Er is discussie over het werkelijke leerniveau van taalmodellen, met de hoop op een toegankelijke en gedemocratiseerde AI-toekomst. Het LLaMA-lek heeft geleid tot open-source optimalisatie op alle platforms; deskundigen hebben echter kritiek op softwarepiraterij en de regulering door AI-bedrijven. OpenAI kan worden geconfronteerd met juridische uitdagingen voor het gebruik van modellen om commerci\xeble resultaten te trainen. De nauwkeurigheid van ChatGPT loopt uiteen: sommigen vinden het nutteloos, terwijl anderen beweren dat GPT-4 op sommige punten een verbetering is. Bing/Sydney en ChatGPT hebben verschillende persoonlijkheden. Het bericht geeft geen nieuwe technologische feiten, maar bespreekt de aard van tekstcompressie."]}),"\n",(0,r.jsx)(n.h2,{id:"van-diep-naar-lang-leren",children:"Van diep naar lang leren?"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://hazyresearch.stanford.edu/blog/2023-03-27-long-learning",children:"Origineel"}),".\nStanford-onderzoekers van het Hazy Research lab verbeteren de sequentielengte in funderingsmodellen voor machinaal leren, met focus op het cre\xebren van bijna lineaire tijdmodellen in sequentielengte die kunnen leiden tot contextlengtes van miljoenen of zelfs miljarden. Het Hyena-model is schaalbaar in sequentielengte tot 2k met behulp van een klein neuraal netwerk dat de convolutiefilters impliciet parametriseert via een ander klein neuraal netwerk met een implementatietijd van O(NlogN). Onderzoekers onderzoeken leermatrices en hun verband met taaltoepassingen. N/A."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35502187",children:"Discussion Service"}),".\nStanford-onderzoekers onderzoeken kostenreductie voor zelfattractie in lange reeksen. Optimaliseren van berekening voor GPU's en co-processoren kan LLM's optimaliseren. Scepsis rond langere-contextmodellen, koppeling van LLM's met andere systemen kan nieuwe oplossingen opleveren. GPT-4 release leidt tot nieuw onderzoek naar next-token prediction, potenti\xeble doorbraken in associatief langetermijngeheugen. Inzicht in K,Q,V-representatie is cruciaal, terwijl RNN's en transformatoren implicaties hebben voor het democratiseren van AI. Langere contextlengtes kunnen worden beschouwd als een nieuwe vorm van zoeken."]}),"\n",(0,r.jsx)(n.h2,{id:"ey-krijgt-verbod-op-nieuwe-controleopdrachten-in-duitsland",children:"EY krijgt verbod op nieuwe controleopdrachten in Duitsland."}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://www.economist.com/business/2023/04/05/ey-gets-banned-from-new-audit-business-in-germany",children:"Origineel"}),".\nEY mag gedurende twee jaar geen nieuwe beursgenoteerde cli\xebnten in Duitsland controleren nadat APAS, de Duitse toezichthouder voor financi\xeble verslaglegging, een boete van 500.000 euro heeft opgelegd, samen met de zwaarste straf ooit. Het besluit, dat komt na een drie jaar durend onderzoek naar de rol van EY in het Wirecard-schandaal, heeft de belegerde accountantsgigant een aanzienlijke financi\xeble en reputatieschade toegebracht. EY had Wirecard een schone lei gegeven totdat het bedrijf in 2020 ten onder ging aan beschuldigingen van grootschalige financi\xeble fraude. Na het wirecard-schandaal heeft EY naar verluidt over een periode van drie jaar tot 2 miljard dollar uitgetrokken om de controles op het gebied van technologie en fraudedetectie te verbeteren, maar geen enkele accountant zal het waarschijnlijk altijd bij het rechte eind hebben."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35501937",children:"Discussion Service"}),'.\nErnst & Young (EY) heeft een verbod gekregen om nieuwe audits uit te voeren in Duitsland wegens onjuiste auditbeslissingen en betrokkenheid bij het Wirecard-schandaal. Adviesbureaus besteden lager betaald personeel uit om het risico te minimaliseren, maar dit kan averechts werken. Auditors bieden alleen redelijke zekerheid en garanderen niet dat er geen fraude zal plaatsvinden. Het gebruik van automatisering en AI kan helpen om frauduleuze activiteiten op te sporen. Auditing moet worden gescheiden van consulting om belangenconflicten te voorkomen. Er is discussie over de waarde van adviesbureaus en de noodzaak van "skin in the game".']}),"\n",(0,r.jsx)(n.h2,{id:"zonsondergang-op-de-zuidpool",children:"Zonsondergang op de Zuidpool"}),"\n",(0,r.jsxs)(n.p,{children:["(",(0,r.jsx)(n.a,{href:"https://brr.fyi/posts/sunset",children:"https://brr.fyi/posts/sunset"}),').\nOp de Zuidpool draait de zon in een bijna perfecte cirkel tegen de klok in aan de hemel, waardoor er geen verschil is tussen "nacht" en "dag". Daardoor is de zonsondergang verspreid over meerdere weken, en daalt de temperatuur snel als de zon laag aan de hemel staat, meestal rond half februari. Het bericht bevat foto\'s van de zonsondergang vanuit verschillende richtingen en een video om het vreemde fenomeen te demonstreren. Het station neemt ook de "zomertijd" in acht, hoewel er geen zichtbaar verschil is tussen de tijden op een bepaalde dag. Het bericht vermeldt dat het Zuidpoolstation de Nieuw-Zeelandse tijd volgt en geeft ook andere gegevens zoals de schemerfase en de eerste sterrenwaarneming van het seizoen.']}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35500966",children:"Discussion Service"}),".\nEen post van Hacker News toont prachtige foto's van de zonsondergang voor een poolnacht van 6 maanden. Reacties bespreken het omgaan met gebrek aan zonlicht, het reguleren van licht, & de bouw van wetenschappelijke faciliteiten. Solargraphy experiment mislukt. De bouw van faciliteiten op de Zuidpool is indrukwekkend. Discussie over het bizarre fenomeen van de rondgang van de zon en het effect ervan op de levensomstandigheden. Antarctica is onherbergzaam en men moet concurreren voor een positie om de zon te zien opkomen en ondergaan. Commentatoren bespreken ook ademhalingsproblemen bij extreme kou. Het artikel biedt een interessante kijk op het leven en onderzoek in Antarctica."]}),"\n",(0,r.jsx)(n.h2,{id:"nederlandse-journalist-die-kritisch-schrijft-over-china-doelwit-in-intimidatieschema",children:"Nederlandse journalist die kritisch schrijft over China doelwit in intimidatieschema"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://nltimes.nl/2023/04/08/dutch-journalist-writes-critically-china-targeted-bizarre-intimidation-scheme",children:"Origineel"}),".\nMarije Vlaskamp, een Nederlandse journaliste die kritisch is over China, is sinds afgelopen najaar het doelwit van een bizarre intimidatieregeling, die onder meer bestond uit bommeldingen en berichten waarin werd ge\xebist dat zij een artikel zou intrekken. Vlaskamp heeft eerder kritisch geschreven over de Chinese staat, met name over de onderdrukking van de Oeigoeren en Chinese dissidenten in Nederland. De Chinese ambassade in Den Haag is het doelwit geweest van een bommelding waarin zowel Vlaskamp als Wang Jingyu, een van de onderwerpen van haar artikelen, werden genoemd. Hoewel de aanvallers van Vlaskamp de Chinese oorsprong van de bedreiging niet proberen te verbergen, heeft de Chinese ambassade ontkend betrokken te zijn bij het aanmoedigen van de aanvallers."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35501969",children:"Discussion Service"}),'.\nNederlandse journalist doelwit van intimidatie; Discussion Service-gebruikers bespreken Chinese inmenging en roepen regeringen op meer te doen. Chinese politiebureaus opereren in Nederland en andere landen, en landen moeten wellicht zelf onderzoek doen naar zogenaamde "grijze acties". Critici stellen dat China\'s acties de soevereiniteit schenden, en sommige politici zijn als gevolg daarvan bedreigd. Discussion Service-gebruikers bespreken de rol van China in recente bommeldingen aan het adres van dissidente journalisten in de VS; debatten over de Chinese regering en haar acties ten aanzien van westerse journalisten. ASML, een Nederlands bedrijf, verschijnt in een context waarin China ernaar streeft de elektronica van het Westen in handen te krijgen.']}),"\n",(0,r.jsx)(n.h2,{id:"usps-faciliteit-in-utah-doet-niets-anders-dan-handschrift-ontcijferen",children:"USPS faciliteit in Utah doet niets anders dan handschrift ontcijferen"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://kutv.com/news/eye-on-utah/what-happens-to-mail-with-band-handwriting-united-states-postal-service-letter-carrier-usps-mailwoman-mailman-cursive-taught-in-schools-unreadable-print-envelopes-undeliverable-packages-salt-lake-city-utah",children:"Origineel"}),".\nDe USPS-vestiging in Utah is gespecialiseerd in het ontcijferen van rommelig handschrift op post. Deze faciliteit heeft meer dan 90 mensen in dienst die de post sorteren en geavanceerde technologie gebruiken om de post te verwerken. De gebruikte technologie kan zelfs handgeschreven adressen scannen en digitaliseren. De faciliteit laat zien hoe technologie zich ontwikkelt om traditionele taken op innovatieve manieren uit te voeren."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35499641",children:"Discussion Service"}),".\nDe USPS-vestiging in Utah is gespecialiseerd in het ontcijferen van cursief handschrift met software van Eagle en Siemens. Handschriftherkenning is een uitdaging geweest voor postmedewerkers, en menselijke tussenkomst is nog steeds vereist. De discussie op Hacker News gaat over de evolutie van arbeid en lonen, eigendom, overheidssubsidies en de voordelen van het schrijven in boeken. De mormoonse gemeenschap van Salt Lake City zou hebben bijgedragen aan het grote aantal bekwame lezers van de vestiging. Sommigen suggereren dat de USPS een mobiele app moet maken, terwijl anderen hun bezorgdheid uiten over privacyschendingen bij het gebruik van priv\xe9gegevens."]}),"\n",(0,r.jsx)(n.h2,{id:"apple-blijft-zich-inspannen-om-te-voorkomen-dat-winkels-zich-verenigen",children:"Apple blijft zich inspannen om te voorkomen dat winkels zich verenigen"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://www.bloomberg.com/news/newsletters/2023-04-09/apple-aapl-continues-efforts-to-keep-retail-stores-from-unionizing-lg9gjdx2",children:"Origineel"}),".\nApple probeert te voorkomen dat zijn winkels zich bij een vakbond aansluiten en diversifieert tegelijkertijd zijn productie van producten en onderdelen buiten China. Het bedrijf heeft onlangs banenverlies en een ander vertrek van leidinggevenden meegemaakt. Het artikel vermeldt ook de aanstaande release van Apple's mixed-reality headset."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35503210",children:"Discussion Service"}),".\nApple beschuldigd van anti-vakbondstactieken, waaronder het onthouden van voordelen; kritiek op onderhandelingstactieken van de vakbond. Discussie over de complexiteit van vakbondsvorming en de gevolgen voor de werknemers. Gallup Poll toont groeiende belangstelling voor een vakbond, vooral bij eerstelijnswerkers. Sommigen bekritiseren de lage lonen en het gebrek aan voordelen in de detailhandel, terwijl anderen beweren dat promoties op basis van anci\xebnniteit en ontslagen negatieve gevolgen kunnen hebben voor bedrijven."]}),"\n",(0,r.jsx)(n.h2,{id:"plrust-10-nu-een-vertrouwde-taal-voor-postgres",children:"PL/Rust 1.0: nu een vertrouwde taal voor Postgres"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://tcdi.github.io/plrust/plrust.html",children:"Origineel"}),'.\nPL/Rust is een laadbare procedurele taal waarmee PostgreSQL functies in Rust geschreven kunnen worden, met toegang tot Postgres\' Server Programming Interface en veilige Rust types over de meeste Postgres-ingebouwde datatypes; PL/Rust functies worden gecompileerd naar native machinecode in plaats van ge\xefnterpreteerd, wat de beste prestaties oplevert. PL/Rust is nu een vertrouwde procedurele taal voor Postgres op x86_64 en aarch64 systemen als aan de juiste compilatievereisten wordt voldaan, waardoor PL/Rust kan leven in een universum van Safe Rust; PL/Rust gebruikt zijn eigen rustc driver om aangepaste lints toe te passen op de LANGUAGE plrust functie van een gebruiker om bepaalde code idiomen toe te passen waarvan ze weten dat ze geen "I-Unsound" problemen hebben. Standaard zal PL/Rust geen kruiscompilatie uitvoeren, maar het moet worden ge\xefnstalleerd en ingeschakeld via configuratie.']}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35501065",children:"Discussion Service"}),".\nPL/Rust 1.0 vertrouwt nu op Postgres als alternatief voor databasefuncties. Cloud providers RDS en Supabase maken implementatie van PL/Rust mogelijk. Heeft uitzonderlijke prestaties maar is nog steeds kwetsbaar voor problemen. Event triggers en DO blokken zijn nog niet opgenomen. Rust heeft toegang tot dev ecosysteem, effici\xebnte types en betere prestaties. Kan optimalisatie voor computationele triggers beperken."]}),"\n",(0,r.jsx)(n.h2,{id:"twitter-blokkeert-likes-en-retweets-die-substack-vermelden",children:"Twitter blokkeert Likes en Retweets die Substack vermelden"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://flipboard.social/@Flipboard/110161362001035875",children:"Original"}),".\nN/A."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35502684",children:"Discussion Service"}),".\nTwitter blokkeert likes/retweets waarin Substack wordt genoemd, waardoor Streisand-effect ontstaat. Elon Musk beschuldigt Substack van schrapen Twitter database, experts vinden verklaring onzinnig. Substack ontkent oneigenlijk gebruik van Twitter API's. Kritiek op Twitter's zoekresultaten, verboden en API gebruiksbeleid. Zorgen over kwaliteit van Substack newsfeed functie. Concurrerende Twitter en Substack evolueren, alternatieve microblogging protocollen onderzocht. Weerstand tegen het veranderen van de kwestie in een spektakel, oproep tot verantwoordelijkheid van het leiderschap. Discussies over API misbruik en Substack's vermeende scraping van Twitter inhoud. Waarschuwing tegen het verwerpen van de benarde situatie van ontslagen Substack werknemers."]}),"\n",(0,r.jsx)(n.h2,{id:"z-bibliotheek-laat-gebruikers-fysieke-boeken-delen",children:"Z-bibliotheek laat gebruikers fysieke boeken delen."}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://torrentfreak.com/z-library-plans-to-let-users-share-physical-books-through-z-points-230408/",children:"Origineel"}),'.\nZ-Library, de grootste opslagplaats van illegaal gekopieerde boeken, breidt zijn diensten uit met een markt voor het fysiek delen van boeken, waarbij miljoenen gebruikers paperbacks kunnen ophalen bij speciale "Z-punten" over de hele wereld. Het is van plan om "inzamel- en opslagpunten" voor boeken te organiseren die "de schakel zullen vormen tussen degenen die hun boeken delen en degenen die ze nodig hebben", wat aanzienlijke opslagruimte en organisatorische inspanningen zal vergen, zodat fulfillmentcentra en logistieke diensten van derden welkom zijn. Een aankondiging op de site lijkt serieus, met mensen die Vietnam, Brazili\xeb, Portugal, Colombia, Iran, Oezbekistan, Nigeria, Spanje, India, Argentini\xeb, Egypte, Frankrijk, Ethiopi\xeb, China en Ghana suggereren als ideale Z-Point locaties, en de site verwelkomt momenteel feedback om zijn dienst te verbeteren.']}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35499065",children:"Discussion Service"}),".\nZ-Library zal gebruikers in staat stellen fysieke boeken te delen, maar uitgevers kunnen de bibliotheek aanklagen; sommigen stellen voor boeken te scannen, auteursrechtwetten te wijzigen of het scannen van boeken te stimuleren. Sommigen discussi\xebren over de haalbaarheid en de gevolgen voor uitgeverijen van een echte markt voor het delen van boeken. Licentiemodellen voor elektronische boeken hebben ongelukkige gevolgen en leiden tot piraterij als vorm van protest. Particuliere lidmaatschapsbibliotheken dateren van voor de openbare bibliotheken en werden vaak uitgeleend."]}),"\n",(0,r.jsx)(n.h2,{id:"perseus---nextjs-alternatief-in-rust",children:"Perseus - NextJS alternatief in Rust"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://framesurge.sh/perseus/en-US/",children:"Origineel"}),".\nPerseus is een Rust framework voor moderne web apps dat on-demand state genereert en doorgeeft aan Sycamore, met Fluent-based I18n toegevoegd voor meertalige functionaliteit, plugins voor maatwerk, alles in WebAssembly voor hoge prestaties, en exporteerbaar/statisch geserveerd, eenvoudig te installeren, en gebruiksvriendelijk."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35500528",children:"Discussion Service"}),".\nGebruikers bespreken Perseus, een op Rust gebaseerd alternatief voor NextJS, waarbij sommigen de voorkeur geven aan JS voor front-end ontwikkeling vanwege de tooling van Rust. Desondanks suggereren de opmars van Rust in de lagere niveaus van de JS-stapel mogelijkheden voor de integratie van JS/TS in Rust-frameworks zoals Perseus. Er ontstaat discussie over de verdiensten van Rust in vergelijking met Go, waarbij sommige gebruikers Rust meer geschikt achten voor low-level programmeren en anderen Go meer geschikt achten voor webontwikkeling. De waarde van een programmeertaal hangt af van waar men woont en wil werken. De release van Perseus trekt de aandacht van tech-savvy personen als een mogelijk sneller alternatief voor Svelte, maar wordt bekritiseerd omdat het moeilijk is voor gebruik in de echte wereld."]}),"\n",(0,r.jsx)(n.h2,{id:"een-baby-gpt",children:"Een Baby GPT"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://twitter.com/karpathy/status/1645115622517542913",children:"Original"}),".\nN/A."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35506069",children:"Discussion Service"}),".\nEen Discussion Service-gebruiker stelt voor binaire reguliere expressies te gebruiken voor taalrelaties, terwijl een ander pleit voor betekenis en bedoeling. Bedenker van baby GPT vergelijkt met Markov keten. Expert beveelt betere wiskundige hulpmiddelen aan. Discussion Service gebruiker vraagt naar implicaties voor het grote publiek. Geen opmerkelijke nieuwe technologie of uitgave."]}),"\n",(0,r.jsx)(n.h2,{id:"twee-soorten-software-ingenieurs",children:"Twee soorten software ingenieurs"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://registerspill.thorstenball.com/p/two-types-of-software-engineers",children:"Origineel"}),".\nHet artikel bespreekt twee soorten software-ingenieurs: Type 1, die aanneemt dat een probleem makkelijk is als het niet technisch is, en Type 2, die aanneemt dat het moeilijk is omdat er mensen bij betrokken zijn. Type 1 gelooft in engineering met hoofdletter E, terwijl type 2 zich richt op mensen en technische problemen ziet als iets waarbij mensen betrokken zijn. Terwijl type 1 vaker voorkomt, begrijpen ingenieurs van type 2 dat engineering chaos en complexiteit met zich meebrengt en streven zij ernaar om ondanks deze uitdagingen te bouwen. Het artikel bevat enkele voorbeelden om de verschillen te illustreren, maar de auteur heeft de grens tussen beide types nog niet precies gedefinieerd of getrokken."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35503784",children:"Discussion Service"}),".\nEen discussie over twee soorten software-ingenieurs, waaronder type 3, en het belang van inzicht in productbeheer. Debat over het evenwicht tussen innovatie en stabiliteit, en de noodzaak van goede documentatie. Dichotomie van vertrouwen op mensen versus implementatie van geautomatiseerde oplossingen in software engineering. Het belang om iedereen op \xe9\xe9n lijn te krijgen over gemeenschappelijke doelen en het begrijpen van grotere bedrijfsbehoeften. Categorisering van software engineers in twijfel getrokken, met de nadruk op het vinden van de oorzaak van problemen. Post dient als stof tot nadenken."]}),"\n",(0,r.jsx)(n.h2,{id:"advanced-linux-programming-2001",children:"Advanced Linux Programming (2001)"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://mentorembedded.github.io/advancedlinuxprogramming/",children:"Origineel"}),".\n'Advanced Linux Programming' van CodeSourceryLLC is een boek dat GNU/Linux ontwikkelaars helpt bij het maken van software met gebruiksvriendelijke mogelijkheden, geavanceerde mogelijkheden zoals multi-threading, interproces communicatie en hardware apparaat interactie, en algemene programmaverbetering. Bovendien leert dit boek ontwikkelaars hoe te werken binnen de GNU/Linux systeemomgeving, inclusief zijn unieke beperkingen, conventies en mogelijkheden. Dit boek kan worden gedownload onder de Open Publication License, Version 1, en wordt geleverd met toegang tot gedekte GNU General Public License code samples. Errata en vertalingen van het boek zijn beschikbaar."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35500197",children:"Discussion Service"}),'.\nHacker News gebruikers bespreken de relevantie van het boek uit 2001, "Advanced Linux Programming" in 2021. Sommige gebruikers stellen voor om verouderde secties bij te werken. Ondanks dat het een beginnersboek is, blijft het een nuttige bron voor Linux API ontwikkeling. Aria2 download applicatie dient als alternatief voor server snelheidsplafonds.']}),"\n",(0,r.jsx)(n.h2,{id:"een-cern-voor-open-source-grootschalige-ai",children:"Een CERN voor Open Source Grootschalige AI"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://www.openpetition.eu/petition/online/securing-our-digital-future-a-cern-for-open-source-large-scale-ai-research-and-its-safety",children:"Origineel"}),".\nLAION e.V. is een petitie gestart voor een internationale, publiek gefinancierde, open-source supercomputer onderzoeksfaciliteit voor AI, vergelijkbaar met CERN, om AI-onderzoek te democratiseren en veiligheidsonderzoek te bevorderen. Platform openPetition wil burgerparticipatie versterken en petities voor verandering ondersteunen. Het initiatief wil democratische principes beschermen tegen ondermijning door een select aantal grote bedrijven. Een Discussion Service-gebruiker merkte op dat 19% van de supporters afkomstig is van laion.ai, terwijl 64% onbekend blijft. Burgers worden aangemoedigd om te doneren ter ondersteuning van de petitie die tractie heeft gekregen op Hacker News."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35501845",children:"Discussion Service"}),".\nEen artikel op openpetition.eu benadrukt de behoefte van Europa aan een CERN-achtig open source initiatief om samenwerking tussen AI-onderzoekers, academici en ondernemers te bevorderen. Samenwerking is nodig om big data te verwerken met grote kapitaalinvesteringen. Open source-projecten zijn nodig om AI-onderzoekers te behouden en de samenleving ten goede te komen in plaats van aandeelhouders. Het succes van CERN maakt het tot een aantrekkelijk model, hoewel sommigen suggereren dat de markt voldoende stimulansen biedt. Het interdisciplinaire karakter van AI vereist dat rekening wordt gehouden met onderling samenhangende kwesties."]}),"\n",(0,r.jsx)(n.h2,{id:"permafrost-engine---een-opengl-rts-game-engine-geschreven-in-c",children:"Permafrost engine - Een OpenGL RTS game engine geschreven in C."}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://github.com/eduard-permyakov/permafrost-engine",children:"Origineel"}),".\nPermafrost Engine is een OpenGL 3.3 Real Time Strategy game engine geschreven in C, gemaakt naar het beeld van oude klassiekers maar met enkele moderne idee\xebn. EVERGLORY is het vlaggenschipspel dat is ontwikkeld met Permafrost Engine, en toont de mogelijkheden van de engine met spelervaring uit de eerste hand. De engine samenvatting bevat een lijst van OpenGL en Python functies, RTS mechanica en cross-platform mogelijkheden. De licentie voor Permafrost Engine is GPLv3, met een speciale linkuitzondering. Bouwinstructies worden gegeven voor zowel Linux als Windows. Een devlog en e-mail voor vragen/opmerkingen over het project of de broncode zijn voorzien voor ge\xefnteresseerde gebruikers."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35504053",children:"Discussion Service"}),".\nOpen-source Permafrost engine krijgt aandacht op Discussion Service voor een nieuw open-source RTS-spel. Everglory spel's lettertype duidelijkheid bekritiseerd. Vergelijking gevraagd met andere RTS-engines. Testen van ontwikkelaars op handheld schermen is belangrijk. Hoop op opleving van het RTS-genre. Gebruikers bespreken open-source RTS engines en gebruikte talen. Vermelding van een andere open-source Frostbite engine implementatie."]}),"\n",(0,r.jsx)(n.h2,{id:"het-sluiten-van-een-oude-ssh-verbinding",children:"Het sluiten van een oude SSH verbinding"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://davidisaksson.dev/posts/closing-stale-ssh-connections/",children:"Origineel"}),".\nHet bericht bespreekt hoe een oude SSH-sessie te sluiten, en stelt dat hoewel de eerste oplossing zou kunnen zijn om de terminal emulator te sluiten, er een betere manier is om ingebouwde SSH escape-reeksen te gebruiken. Het bericht legt uit hoe de tilde (",(0,r.jsx)(n.del,{children:") prefix gevolgd door een commando meerdere verborgen commando's in SSH clients kan activeren, inclusief het 'terminate session' commando ("}),".). Het bericht merkt op dat aandacht moet worden besteed aan het feit dat een voorafgaande newline vereist is, en biedt een kleine opmerking voor mensen die een toetsenbord met een nordic lay-out gebruiken om het tilde karakter te typen. Het bericht eindigt met een bespreking van wat te doen na gebruik van de escape-sequentie 'terminate session'."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35504402",children:"Discussion Service"}),".\nEen Discussion Service gebruiker geeft een SSH-tip. Een andere wijst op een layout probleem maar geeft een workaround. Het configureren van EscapeChar wordt voorgesteld. Discussie over SSH manpage, springende hosts, en SSH verbindingen. Sticky SSH sessie wordt gewenst. Autossh aanbevolen voor auto-attach, en Mosh voor het veranderen van port forwarding. Encryptie details en aanvullende tips. Waarschuwing tegen het gebruik van Alpine Linux."]}),"\n",(0,r.jsx)(n.h2,{id:"flatcar-container-linux",children:"Flatcar Container Linux"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://www.flatcar.org/",children:"Origineel"}),".\nFlatcar Container Linux is een community Linux distributie die ontworpen is voor container workloads met hoge veiligheid en weinig onderhoud. Het OS-image bevat alleen de tools die nodig zijn om containers te draaien zonder package manager of configuratiedrift. Het onveranderlijke bestandssysteem en geautomatiseerde atomaire updates bieden een sterke basis voor de beveiliging van de infrastructuur. De ingebouwde beveiligingsfuncties van Flatcar Container Linux en het verminderde aanvalsoppervlak vereenvoudigen het beheer van het besturingssysteem. Het bevat tools om grootschalige infrastructuren te beheren en ondersteunt wereldwijde initiatieven. Geautomatiseerde, atomaire updates zorgen ervoor dat u de meest stabiele, veilige en up-to-date Flatcar-versie draait. Het is een drop-in vervanging voor CoreOS Container Linux."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35503928",children:"Discussion Service"}),".\nMicrosoft's Flatcar Container Linux update en gaat door na overname en biedt een alternatief voor CloudInit. De onveranderlijke infrastructuurbenadering wint aan populariteit ondanks de technische problemen van Ignition. Flatcar Linux-ontwikkelaars stellen een vriendelijke update voor. Discussion Service gebruikers bespreken het toevoegen van containers en suggereren een UEFI firmware voor betere prestaties."]}),"\n",(0,r.jsx)(n.h2,{id:"microsoft--jarvis-een-systeem-om-llms-te-verbinden-met-de-ml-gemeenschap",children:"Microsoft / JARVIS: een systeem om LLM's te verbinden met de ML-gemeenschap"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://github.com/microsoft/JARVIS",children:"Origineel"}),".\nMicrosoft en Hugging Face hebben het Labs-project JARVIS onthuld, een AI-assistent voor het verbinden van taal- en machine-learningmodellen. JARVIS gebruikt een groot taalmodel (LLM) om verzoeken te begrijpen en te analyseren, en maakt vervolgens gebruik van een selectie van talrijke expertmodellen om de vereiste taak uit te voeren. Het bestaat uit vier fasen: taakplanning, modelselectie, taakuitvoering en het genereren van antwoorden. De gebruiker kan genieten van een lichtgewicht ervaring met JARVIS zonder de modellen lokaal te implementeren door de CLI-modus of de webpagina te activeren, die een gebruiksvriendelijke interface toont die met JARVIS communiceert."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35500472",children:"Discussion Service"}),".\nMicrosoft lanceert JARVIS om LLM's te verbinden met ML-gemeenschap met behulp van regelgebaseerde benaderingen en machinaal leren. Sommigen speculeren of autonome AI-agenten fraude of oplichting kunnen plegen, maar lezers zijn vooral enthousiast. Jarvis genereert tekst en afbeeldingen op basis van door LLM's gekozen modellen, maar sommigen maken zich zorgen over handelsmerkproblemen en afluisteren."]}),"\n",(0,r.jsx)(n.h2,{id:"bolvormige-tokamak-bereikt-cruciale-plasmatemperaturen",children:"Bolvormige tokamak bereikt cruciale plasmatemperaturen"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://www.eetimes.com/spherical-tokamak-achieves-crucial-plasma-temperatures/",children:"Origineel"}),".\nDe sferische tokamak van Tokamak Energy bereikte ionentemperaturen van meer dan 100 miljoen graden Kelvin - een kritieke stap in de ontwikkeling van technologie voor fusie-energie. De kleine afmetingen, plasmastabiliteit en magnetische opsluitingseigenschappen van sferische tokamaks maken ze een aantrekkelijke keuze voor commerci\xeble fusie-energieproductie. Steven McNamara, wetenschappelijk directeur van Tokamak Energy, gelooft dat het bedrijf binnen 10 jaar fusie-energie op het elektriciteitsnet kan brengen, als aanvulling op andere hernieuwbare energiebronnen. De doorbraak maakt gebruik van Thomson-verstrooiing om de temperatuur en dichtheid op meerdere punten te meten, wat de weg vrijmaakt voor goedkope, inzetbare commerci\xeble fusiecentrales. De technologie heeft ook potenti\xeble toepassingen in de duurzame luchtvaart en de productie van waterstofbrandstof."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35505342",children:"Discussion Service"}),".\nEen bolvormige tokamak bereikt cruciale plasmatemperaturen. Sommige gebruikers bespreken structurele problemen, \xe9\xe9n beveelt een fusie-energie podcast aan. Het artikel verklaart de noodzaak van een warmtewisselaar en de lagere kosten van het nieuwe ontwerp. De levensvatbaarheid van commerci\xeble fusie wordt besproken. Verdubbeling van de magneetsterkte in kleinschalige proeven bevordert de vooruitgang. Afval en veiligheidsvoordelen van fusie ten opzichte van kernsplijting worden opgemerkt. Sferische tokamaks zijn een geavanceerde toepassing. De bereikte mijlpaal is nog niet bruikbaar, maar er wordt vooruitgang geboekt op het gebied van magneetsterkte."]}),"\n",(0,r.jsx)(n.h2,{id:"de-eerste-paaseieren-van-het-spel-waren-een-daad-van-bedrijfsrebellie",children:"De eerste 'paaseieren' van het spel waren een daad van bedrijfsrebellie..."}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://thehustle.co/the-first-easter-eggs-were-an-act-of-corporate-rebellion/",children:"Origineel"}),'.\nDe eerste paaseieren in videospellen waren het gevolg van het feit dat ontwerpers geen krediet kregen voor hun werk, wat leidde tot verborgen boodschappen in spellen. De eerste Easter egg werd gevonden in Atari\'s spel "Adventure" uit 1980, gemaakt door Warren Robinett. De traditie van verborgen boodschappen werd voortgezet in de arcadespellen van de jaren 1970 om erkenning en individualiteit te zoeken. Robinetts paasei verhoogde zijn status en hij ontwikkelde een succesvol softwarebedrijf. De Tech Times bericht over verschillende cookies die door bedrijven worden gebruikt om het online gedrag van gebruikers te volgen en advertenties te personaliseren, maar deze zijn nog niet geclassificeerd.']}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35503260",children:"Discussion Service"}),".\nEen post van Hacker News over bedrijfsrebellie via paaseieren bevat anekdotes en actueel bedrijfsbeleid. De interesse van de lezers kan gewekt worden door de historische relevantie en de evolutie van de rol van het paasei. Huidige Easter eggs drukken bedrijfstrots uit, geen insubordinatie. Code reviews voorkomen paaseieren. Voormalige techbedrijven vallen vaak onder nieuw benoemde MBA's. Warren Robinett wordt geprezen voor Adventure game. U2's lid en Atari fan hebben verschillende namen."]}),"\n",(0,r.jsx)(n.h2,{id:"modulaire-fouten-in-rust",children:"Modulaire fouten in Rust"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://sabrinajewson.org/blog/errors",children:"Origineel"}),".\nHet artikel bespreekt het belang van modulaire foutafhandeling en introduceert het principe dat fouttypes dicht bij hun eenheid van fout liggen, met een hypothetische Rust-bibliotheek als voorbeeld. Problemen met onbehulpzame foutmeldingen, onuitbreidbaarheid en moeilijk te matchen fouten worden geschetst, en oplossingen zoals de .source() methode en betere fouttypeconstructie worden voorgesteld. Het fouttype van de voorbeeldbibliotheek wordt opgesplitst in drie verschillende types met goede backtraces en nauwkeurige foutmatching, en I/O-fouten worden verklaard door een meer gestructureerd fouttypeontwerp. Het artikel benadrukt het belang van goede backtraces, uitbreidbaarheid, inspecteerbaarheid, stabiliteit en modulariteit bij foutafhandeling, en suggereert dat goede foutafhandeling het leren waard is."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35502874",children:"Discussion Service"}),".\nDe foutmeldingen van Rust zijn populair, maar er zijn gevarieerde fouttypes nodig. SNAFU maakt het mogelijk om unieke sporen te produceren. Afzonderlijke fouten verminderen de wildgroei en maken de afhandeling gemakkelijker, maar pas op voor de ondersteuning van openbare API's. Loggen en be\xebindigen zou niet de primaire aanpak moeten zijn voor het debuggen van bibliotheken. Granulaire of ondoorzichtige fouten met beschrijvingen verdienen de voorkeur. Gecontroleerde uitzonderingen in Java worden geprezen. De fatale fout van Java is het ontbreken van algebra\xefsche types."]}),"\n",(0,r.jsx)(n.h2,{id:"68-95-997-regel",children:"68-95-99.7 Regel"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://en.wikipedia.org/wiki/68%E2%80%9395%E2%80%9399.7_rule",children:"Original"}),".\nDe 68-95-99,7 regel is een statistische benadering die het percentage waarden binnen een standaardafwijking van het gemiddelde in een normale verdeling schat. De regel stelt dat ruwweg 68%, 95% en 99,7% binnen respectievelijk \xe9\xe9n, twee en drie standaardafwijkingen vallen. Deze regel wordt veelvuldig gebruikt op verschillende gebieden, zoals kwaliteitscontrole en gegevensanalyse. Het is een snelle manier om een ruwe kansschatting te maken voor een normaal veronderstelde populatie. De formule kan worden toegepast op verschillende verdelingen, en kan helpen bij het identificeren van uitschieters in de gegevensanalyse."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35501780",children:"Discussion Service"}),".\nHet commentaar van Discussion Service bespreekt de beperkingen van de 68-95-99,7 regel bij het analyseren van gegevens. Het werk van Nassim Nicholas Taleb en de ongelijkheid van Chebyshev worden genoemd. Kanttekeningen bij financi\xeble handel & geschiedenis van Amerikaanse optiemarkt. Experts beweren dat hoge IQ-scores onbetrouwbaar zijn & dat de schaal willekeurig is."]}),"\n",(0,r.jsx)(n.h2,{id:"unicodeplots",children:"UnicodePlots"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://github.com/JuliaPlots/UnicodePlots.jl",children:"Origineel"}),".\nDe UnicodePlots bibliotheek is een hoog-niveau plotten gereedschap voor gebruik in Julia's REPL dat spreidingsplots, lijnplots en heatmaps bevat. Het ondersteunt ook fysieke grootheden van Unitful.jl en intervallen van IntervalSets.jl, maakt het mogelijk plot features aan te passen zoals plot hoogte en breedte en reverse/flip plot assen, en ondersteunt het opslaan van plots als PNG of TXT."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35505591",children:"Discussion Service"}),".\nHet op Julia gebaseerde UnicodePlots toont grafieken en histogrammen op de terminal voor snelle visualisaties op externe servers. Het voorziet in een behoefte aan snelle datavisualisatie in de terminal, zonder een volledige grafische stack te installeren. UnicodePlots is vooral overgenomen in een Ruby port, en een Python versie die compatibel is met Matplotlib. Er is momenteel een trend naar tekstgebruikersinterfaces, waardoor een splitsing ontstaat tussen Electron voor eindgebruikersapps en TUI voor draagbare tools. Het heeft 100% codedekking, ondersteunt vergelijkende histogrammen, en laat gebruikers toe om gegevens te kopi\xebren en te plakken in commentaar of beschrijvingen. Hoewel het geen geheel nieuwe technologie is, is UnicodePlots een nuttig hulpmiddel voor wie snel gegevens moet beoordelen."]}),"\n",(0,r.jsx)(n.h2,{id:"digitale-verzamelobjecten-op-instagram-loopt-af",children:"Digitale verzamelobjecten op Instagram loopt af"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://help.instagram.com/1824155514623095",children:"Original"}),".\nVanaf 11 april 2023 zal Instagram zijn ondersteuning voor digitale verzamelobjecten afbouwen, wat gevolgen heeft voor het maken van nieuwe digitale verzamelposten, de zichtbaarheid van digitale portemonnees en de toegankelijkheid van blockchaininformatie. De verwijdering van digitale verzamelgegevens zal in overeenstemming zijn met het privacybeleid van Instagram en de gebruiksvoorwaarden van Digital Collectibles, maar gebruikers kunnen v\xf3\xf3r de deadline een verzoek indienen om hun informatie te downloaden. De inhoud van digitale portemonnees van derden zal niet worden be\xefnvloed."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35501074",children:"Discussion Service"}),".\nDe digitale verzamelobjecten van Instagram verliezen stoom, maar web3-gelovigen laten zich niet afschrikken. De NFT-ruimte moet werk maken van eigendomsnormen en zakelijke goedkeuring. De avatars van Reddit verkopen goed, maar polygoon NFT's worden als minder waardevol gezien. De winter is welkom voor bouwers om infrastructuur aan te leggen en voor traditionele bedrijven om kennis te maken met gedecentraliseerde netwerken. Het succes van Pokemonkaarten en Reddit-functies wordt vergeleken met het concept van schaarste. De term \"Web3\" is misschien voorbarig en oplichters en bouwers zitten in verschillende kampen. Er is scepsis en bezorgdheid over de NFT-hype, investeringsrisico's en geestelijke gezondheid. Cult betrokkenheid in industrie\xebn, crypto, en AI risico's worden besproken. Het nut van ChatGPT wordt besproken, en gebruikers richten zich op frisse inzichten zonder politieke of religieuze taal. De context van geavanceerde technologie met betrekking tot communicatie en synchronisatie van de aarde wordt besproken, met uiteenlopende meningen over de waarde van NFT en de impact ervan op de samenleving."]}),"\n",(0,r.jsx)(n.h2,{id:"de-uitspraak-die-de-toekomst-van-bibliotheken-bedreigt",children:"De uitspraak die de toekomst van bibliotheken bedreigt"}),"\n",(0,r.jsxs)(n.p,{children:["(",(0,r.jsx)(n.a,{href:"https://www.theatlantic.com/ideas/archive/2023/04/internet-archive-libraries-federal-court-ruling/673615/",children:"https://www.theatlantic.com/ideas/archive/2023/04/internet-archive-libraries-federal-court-ruling/673615/"}),').\nEen uitspraak van een federale rechtbank dat controlled digital lending (CDL) in strijd is met het auteursrecht kan desastreuze gevolgen hebben voor bibliotheken, zoals het moeten kiezen tussen het kopen van dure ebook-licenties van uitgevers of het uitbreiden van hun collecties; het Internet Archive (IA), een non-profit organisatie die digitale kopie\xebn uitleent van de miljoenen boeken die het heeft verzameld en gedigitaliseerd, was het middelpunt van een rechtszaak door verschillende boekenuitgevers die het in 2020 aanklaagden wegens inbreuk op het auteursrecht; en het was dit CDL-uitleenmodel dat de rechtbank vorige maand veroordeelde, dat "oneerlijke macht over de toekomst van boeken en bibliotheken" zou kunnen hebben, volgens advocaat Corynne McSherry van de Electronic Frontier Foundation, die de IA vertegenwoordigt in haar beroep tegen de uitspraak.']}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35502238",children:"Discussion Service"}),".\nEen uitspraak van de rechtbank over gecontroleerde digitale uitlening en auteursrechtwetten heeft discussies aangewakkerd, met suggesties om de lengte van het auteursrecht te verkorten om verlies van kennis te voorkomen; sommigen suggereren dat de winst van uitgevers niet het punt mag zijn bij het uitlenen van CDL materiaal. Bibliotheken hebben zich aangepast om openbare amusementscentra te worden, en de toegang van het publiek tot bronnen is essentieel; bibliothecarissen gebruiken het advies van deskundigen om de populariteit van de oplage, de waarde van het boek en de missie van de bibliotheek tegen elkaar af te wegen bij het weggooien van boeken. Rechtszaken van uitgevers tegen de onbeperkte royalty-vrije digitale distributie van Internet Archive brengen de inkomsten van schrijvers in gevaar, en gecontroleerde digitale uitleen kan de bescherming van auteursrechten in gevaar brengen. Het snijvlak van digitaal en fysiek eigendom blijft een onderwerp van discussie; de discussies bieden unieke perspectieven op de onderhavige kwestie."]}),"\n",(0,r.jsx)(n.h2,{id:"do-kwon-zette-illegaal-geld-van-luna-om-in-bitcoin",children:"Do Kwon zette illegaal geld van LUNA om in Bitcoin."}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://cointelegraph.com/news/do-kwon-converted-stolen-funds-from-luna-to-bitcoin-s-korean-prosecutors",children:"Original"}),".\nZuid-Koreaanse aanklagers hebben voor bijna 314,2 miljoen dollar aan illegale activa ge\xefdentificeerd in verband met de medeoprichter van Terraform Labs, Do Kwon, en zijn medewerkers, waarvan Kwon alleen al voor ongeveer 69 miljoen dollar. De aanklagers hebben contact opgenomen met Binance om elk verzoek tot opname in verband met Kwon te stoppen. Kwon heeft naar verluidt het grootste deel van de illegale fondsen, die ongeveer 414,5 miljard won bedragen, omgezet in Bitcoin, en geen van de activa die met hem in verband staan kunnen worden teruggevorderd of vallen onder de jurisdictie van de Zuid-Koreaanse autoriteiten. Terra was een crypto-ecosysteem dat in mei 2022 instortte, waarbij de voormalige CEO Kwon werd beschuldigd van het overhevelen van Bitcoin ter waarde van bijna 100 miljoen dollar na de ineenstorting."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35499996",children:"Discussion Service"}),".\nOn-chain gegevens tonen Terraform Labs' Do Kwon's Bitcoin conversie van frauduleuze LUNA fondsen. Legt beperkingen bloot van het opsporen van fraude via traditionele banken. Discussion Service-gebruikers bespreken privacyinstrumenten en eerlijkheid in de cryptoruimte. Debat of intelligentie is ge\xebvolueerd voor concurrentie of samenwerking, waarbij sommigen pleiten voor het laatste. Concurrentie en predatie drijven concurrentie, maar algemene trend is om te blijven debatteren over rollen in intelligentie evolutie."]}),"\n",(0,r.jsx)(n.h2,{id:"interview-met-andrew-kelley-zig-creator-2021",children:"Interview met Andrew Kelley (Zig Creator) (2021)"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://corecursive.com/067-zig-with-andrew-kelley/",children:"Origineel"}),".\nAndrew Kelley bespreekt zijn ervaringen met het ontwikkelen van de programmeertaal Zig, de uitdagingen van het combineren van een fulltime baan met open-source werk, het belang van onderhandelen over eigendom van intellectueel eigendom, en de morele kwesties rond commercieel forken in de open-source gemeenschap. Zig is een non-profit programmeertaal gericht op het verbeteren van de geheugenveiligheid en het verminderen van de informatie-overload voor gebruikers. Kelley ziet Zig als de taal bij uitstek voor besturingssystemen en tekstboeken, wat leidt tot betere prestaties van applicaties, geheugengebruik en stabiliteit. Tech Times bericht ook over verschillende programmeergerichte videocursussen die online beschikbaar zijn."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35502151",children:"Discussion Service"}),".\nCorecursive's interview met Zig Creator Andrew Kelley inspireert luisteraars om alle eerdere podcasts op de website te downloaden, waarbij crowd funding projecten en persoonlijk advies in aparte commentaren worden besproken. E\xe9n luisteraar waardeert de vriendelijke sfeer van het #chicken scheme kanaal. Een ander benadrukt de transparantie van Andrew Kelley in een gevorkt Zig-incident, maar een gebruiker reageert negatief op zijn interactie met Kelley. Over het algemeen genieten de luisteraars van het interview over Zig en de technische geschiedenis van SQLite."]}),"\n",(0,r.jsx)(n.h2,{id:"supavisor---een-postgres-connection-pooler-geschreven-in-elixir",children:"Supavisor - een Postgres connection pooler geschreven in Elixir"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://github.com/supabase/supavisor",children:"Origineel"}),".\nSupavisor is een Postgres connection pooler die miljoenen Postgres-eindklantverbindingen kan proxy-en in een stateful pool van native Postgres-databaseverbindingen via een schaalbare, cloud-native architectuur. Dit systeem vereenvoudigt Postgres-clusterbeheer voor databasebeheerders door eenvoudige configuratie van hoog beschikbare Postgres-clusters, terwijl het effici\xebnt gebruik maakt van resources, schaalbaar, multi-tenant en Cloud-native is. Er zijn al benchmarks en Load tests beschikbaar, waaruit blijkt dat het een miljoen Postgres-verbindingen op een cluster aankan en het kan miljoenen verbindingen absorberen, waardoor het een geweldige keuze is voor ontwikkelaars die vanuit Serverless-omgevingen verbinding maken met Postgres. Toekomstig werk omvat load balancing, session pooling, Postgres high-availability management, en API's zoals Postgres binary, HTTPS, en nog veel meer. Jos\xe9 Valim en het Dashbit team hebben geholpen om de Supavisor ontwerpbeslissingen te nemen, en het is ge\xefnspireerd door producten als PgBouncer, Amazon RDS Proxy, Google Cloud SQL Proxy, en meer."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35501718",children:"Discussion Service"}),".\nSupabase CEO introduceert Supavisor, een Postgres connection pooler gebouwd met Elixir, met nadruk op de gelijkenis met Pgbouncer en ontworpen voor multi-tenancy. De benchmarks van Supavisor geven aan dat het een hoge doorvoer aankan terwijl het 7.8G RAM en ~50% CPU verbruikt op een 64vCPU machine. Supabase is van plan om Supavisor voor al zijn databases te hebben, zodat het computergebruik kan worden opgeschaald zonder downtime. Discussion Service-gebruikers vragen om de toevoeging van prepared statements in transaction pooling modus en stellen voor om Nimble_pool te gebruiken in plaats van Poolboy, terwijl ze de concurrency-ondersteuning en fouttolerantie van Elixir prijzen. Een Discussion Service gebruiker deelt werkervaring met Pgbouncer op 4 vCPU machines en een ander vertelt over hun pool van gemeenschappelijke Pgbouncers die naar verschillende PostgreSQL instances routeren met behulp van Google's Cloud SQL proxy."]}),"\n",(0,r.jsx)(n.h2,{id:"nieuwe-beschuldigingen-van-plagiaat-tegen-roy-lichtenstein",children:"Nieuwe beschuldigingen van plagiaat tegen Roy Lichtenstein"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://www.theguardian.com/artanddesign/2023/apr/09/new-allegations-of-plagiarism-against-roy-lichtenstein",children:"Origineel"}),'.\nEr zijn nieuwe beschuldigingen van plagiaat geuit tegen Roy Lichtenstein. In een nieuwe film wordt beweerd dat honderden van zijn werken kunnen worden herleid tot andere kunstenaars. De documentaire beweert dat meer dan 30 komische kunstenaars werden "toege\xebigend" door de grondlegger van de pop-artbeweging, die miljoenen verdiende aan de verkoop van zijn werk, terwijl de oorspronkelijke kunstenaars die werden gekopieerd een sober en zelfs berooid leven leidden. Terwijl sommigen het werk van Lichtenstein verdedigen als "toe-eigening", noemen critici het stelen, waarbij "regelrechte plagiaat" wordt genoemd naast "technisch en artistiek" superieure werken die door Lichtenstein zijn gekopieerd.']}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35501868",children:"Discussion Service"}),".\nNieuwe beschuldigingen van plagiaat tegen Roy Lichtenstein leiden tot discussie over ethiek, originaliteit en gepastheid in de kunstwereld. Discussion Service-gebruikers discussi\xebren over de vraag of het werk van Lichtenstein transformatief is of schaamteloos stelen met minimale veranderingen. Er is bezorgdheid over auteursrecht en intellectuele eigendom, maar ook over de culturele waarde van stripkunst versus kunst. Het debat omvat meningen over de aard van kunst, creatie en waarde in de kunstwereld. De oorspronkelijke striptekenaars werden volgens het bericht vaak gezien als laagbetaalde handelswaar."]})]})}function c(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(g,{...e})}):g(e)}}}]);